      </div>

      <div class="form-field">
        <label for="email">Email address</label>
        <input id="email" name="email" type="email" autocomplete="email" required aria-describedby="email-error">
        <div class="error-message" id="email-error" aria-live="polite"></div>
      </div>

      <div class="form-field">
        <label for="phone">Phone number</label>
        <input
          id="phone"
          name="phone"
          type="tel"
          inputmode="tel"
          autocomplete="tel"
          placeholder="+1 555 123 4567"
          aria-describedby="phone-help phone-error"
        >
        <div class="helper-text" id="phone-help">Optional. Use a format like +1 555 123 4567 or 555-123-4567.</div>
        <div class="error-message" id="phone-error" aria-live="polite"></div>
      </div>

      <div class="actions">
        <button type="submit">Submit request</button>
      </div>

      <div class="status" id="form-status" aria-live="polite"></div>
    </form>
