    const errors = {
      fullName: document.getElementById('full-name-error'),
      email: document.getElementById('email-error'),
      phone: document.getElementById('phone-error')
    };
    const status = document.getElementById('form-status');

    const phonePattern = /^(?:\+?\d{1,3}[-.\s]?)?(?:\(?\d{3}\)?[-.\s]?)?\d{3}[-.\s]?\d{4}$/;

    function setError(input, message) {
      const errorEl = errors[input.name === 'fullName' ? 'fullName' : input.name];
      errorEl.textContent = message;
      input.setAttribute('aria-invalid', message ? 'true' : 'false');
    }

    function validateFullName() {
      const input = fields.fullName;
      if (!input.value.trim()) {
        setError(input, 'Full name is required.');
        return false;
      }
      setError(input, '');
      return true;
    }

    function validateEmail() {
      const input = fields.email;
      if (!input.value.trim()) {
        setError(input, 'Email address is required.');
        return false;
