      if (!phonePattern.test(value)) {
        setError(input, 'Enter a valid phone number, such as +1 555 123 4567.');
        return false;
      }
      setError(input, '');
      return true;
    }

    function validateField(input) {
      if (input === fields.fullName) return validateFullName();
      if (input === fields.email) return validateEmail();
      return validatePhone();
    }

    Object.values(fields).forEach((input) => {
