      input.addEventListener('input', () => {
        if (input.getAttribute('aria-invalid') === 'true') {
          validateField(input);
        }
        status.textContent = '';
      });
    });

    form.addEventListener('submit', (event) => {
      event.preventDefault();
      status.textContent = '';

      const isValid = [validateFullName(), validateEmail(), validatePhone()].every(Boolean);
      if (!isValid) return;

      status.textContent = 'Thanks — your message has been prepared for submission.';
      form.reset();
      Object.values(fields).forEach((input) => input.removeAttribute('aria-invalid'));
      Object.values(errors).forEach((errorEl) => (errorEl.textContent = ''));
